/** The death texture key for a monster family, or null. */
export function monsterDeathKey(family) {
  return DEATH_ART.mon[family] ? `death_mon_${family}` : null;
}
/** The death texture key for a living NPC texture, or null. */
export function npcDeathKey(texKey) {
  return DEATH_ART.npc[texKey] ? `death_${texKey}` : null;
}
